import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.57.4';
const db=createClient('https://psvugkyzlhzemptavpdh.supabase.co','sb_publishable_r6nBnvXMVpVx2HshzFXxSQ_8vr0Mnck');
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={user:null,tables:[],players:[],sheets:[],table:null,view:'fichas',filter:'all',search:'',sheet:null,tab:'principal',dirty:false,saving:false,conflict:false,channel:null,connected:false};
let timer,toastTimer,authMode='login',refreshTimer;
const abilities=[['str','Força'],['dex','Destreza'],['con','Constituição'],['int','Inteligência'],['wis','Sabedoria'],['cha','Carisma']];
const skills=[['Atletismo','str'],['Acrobacia','dex'],['Furtividade','dex'],['Prestidigitação','dex'],['Arcanismo','int'],['História','int'],['Investigação','int'],['Natureza','int'],['Religião','int'],['Intuição','wis'],['Lidar com animais','wis'],['Medicina','wis'],['Percepção','wis'],['Sobrevivência','wis'],['Atuação','cha'],['Enganação','cha'],['Intimidação','cha'],['Persuasão','cha']];
const mod=n=>Math.floor((Number(n??10)-10)/2),signed=n=>n>=0?'+'+n:n;
const gm=()=>state.tables.some(t=>t.id===state.table);
const table=()=>state.tables.find(t=>t.id===state.table);
const players=()=>state.players.filter(p=>p.table_id===state.table&&p.active);
const sheets=()=>state.sheets.filter(s=>s.table_id===state.table);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}
function fail(error){console.error(error);toast(error?.message||'Não foi possível concluir. Tente novamente.');}
async function result(promise){const r=await promise;if(r.error)throw r.error;return r.data;}
function brand(){return '<div class="brand"><span class="mark">✧</span><div>Grimório<small>FICHAS DE D&D</small></div></div>'}
function login(){ $('#app').innerHTML=`<div class="login"><aside class="login-art">${brand()}<div class="ornament" aria-hidden="true">✧</div><div class="intro"><div class="eyebrow">CADA PERSONAGEM, UMA HISTÓRIA</div><h1>Sua aventura.<br>Em boas mãos.</h1><p>Um lugar para as fichas da sua mesa. Cada ponto de vida, cada magia, cada mudança — juntos, em tempo real.</p></div><div class="note">D&D 2024 · Fichas em português · Segredos guardados</div></aside><main class="login-form"><div class="eyebrow">BEM-VINDO À MESA</div><h2>${authMode==='signup'?'Abra seu grimório':'A aventura continua'}</h2><p>Entre para acessar suas fichas e sua mesa.</p><div class="tabs"><button data-auth="login" class="${authMode==='login'?'active':''}">Entrar</button><button data-auth="signup" class="${authMode==='signup'?'active':''}">Criar conta</button></div><form id="auth-form"><label>E-mail<input name="email" type="email" autocomplete="email" required placeholder="voce@exemplo.com"></label><label>Senha<input name="password" type="password" minlength="8" autocomplete="${authMode==='signup'?'new-password':'current-password'}" required placeholder="Pelo menos 8 caracteres"></label><button class="primary">${authMode==='signup'?'Criar minha conta':'Entrar no Grimório'} →</button><p id="auth-message" role="status" class="note"></p></form><p class="note">É jogador? Use o mesmo e-mail que seu mestre adicionou à mesa. Suas fichas aparecerão após o login.</p></main></div>`;
 document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;login()});
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const f=new FormData(e.target);try{const credentials={email:f.get('email').trim().toLowerCase(),password:f.get('password')};const r=authMode==='signup'?await db.auth.signUp({...credentials,options:{emailRedirectTo:location.origin}}):await db.auth.signInWithPassword(credentials);if(r.error)throw r.error;if(!r.data.session)$('#auth-message').textContent='Conta criada. Confirme seu e-mail e depois volte aqui para entrar.';else await start(r.data.session.user);}catch(err){$('#auth-message').textContent=err.message==='Invalid login credentials'?'E-mail ou senha incorretos.':err.message;}finally{b.disabled=false;}};
}
async function load(){const [ts,ps,ss]=await Promise.all([result(db.from('dnd_tables').select('*').order('created_at')),result(db.from('dnd_players').select('*').order('created_at')),result(db.from('dnd_sheets').select('*').order('updated_at',{ascending:false}))]);state.tables=ts;state.players=ps;state.sheets=ss;const ids=[...new Set([...ts.map(t=>t.id),...ps.filter(p=>p.active).map(p=>p.table_id)])];if(!ids.includes(state.table))state.table=ids[0]||null;}
async function start(user){state.user=user;await load();render();if(state.channel)await db.removeChannel(state.channel);state.channel=db.channel('grimorio-'+user.id).on('postgres_changes',{event:'*',schema:'public',table:'dnd_sheets'},changed).on('postgres_changes',{event:'*',schema:'public',table:'dnd_players'},changed).on('postgres_changes',{event:'*',schema:'public',table:'dnd_tables'},changed).subscribe(status=>{state.connected=status==='SUBSCRIBED';const el=$('#connection');if(el)el.textContent=state.connected?'Conectado em tempo real':'Reconectando…';if(state.connected)changed();});}
function changed(){clearTimeout(refreshTimer);refreshTimer=setTimeout(async()=>{try{await load();if(state.sheet){const fresh=state.sheets.find(s=>s.id===state.sheet.id);if(!fresh){state.sheet=null;state.dirty=false;clearTimeout(timer);toast('O acesso a esta ficha foi removido.');render();return;}if(state.dirty||state.saving)return;const focus=document.activeElement;if(focus?.matches('[data-field]'))return;state.sheet=structuredClone(fresh);}render();}catch(err){fail(err)}},200);}
function render(){if(!state.user)return login();const ids=[...new Set([...state.tables.map(t=>t.id),...state.players.filter(p=>p.active).map(p=>p.table_id)])];$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div><div class="eyebrow">SUA MESA</div><select id="table-select" aria-label="Selecionar mesa">${ids.length?ids.map(id=>`<option value="${id}" ${id===state.table?'selected':''}>${esc(state.tables.find(t=>t.id===id)?.name||'Mesa do mestre · '+id.slice(0,4))}</option>`).join(''):'<option>Nenhuma mesa</option>'}</select></div><nav><button data-view="fichas" class="${state.view==='fichas'?'active':''}">▤ &nbsp; Fichas da mesa</button>${gm()?`<button data-view="secretas" class="${state.view==='secretas'?'active':''}">◇ &nbsp; Arquivo secreto</button><button data-view="jogadores" class="${state.view==='jogadores'?'active':''}">♧ &nbsp; Jogadores</button>`:''}<button id="new-table">＋ &nbsp; Criar mesa</button></nav><div class="foot"><div class="eyebrow">APENAS AS FICHAS.</div>Mais tempo para jogar.<br>Menos papel na mesa.<hr style="border:0;border-top:1px solid var(--line);margin:20px 0">Inspirado na ficha D&D 2024.</div></aside><main class="main"><header class="topbar"><span>${gm()?'PAINEL DO MESTRE':'ÁREA DO JOGADOR'}</span><span id="connection" class="status">${state.connected?'Conectado em tempo real':'Conectando…'}</span><button class="quiet" id="logout" title="${esc(state.user.email)}">Sair</button></header><div id="content"></div></main></div>`;
 $('#table-select').onchange=async e=>{if(!await leave())return render();state.table=e.target.value;state.sheet=null;state.view='fichas';render()};
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>{if(!await leave())return;state.view=b.dataset.view;state.sheet=null;render()});
 $('#new-table').onclick=async()=>{if(await leave())newTable()};$('#logout').onclick=async()=>{if(!await leave())return;await db.auth.signOut();state.user=null;state.sheet=null;state.connected=false;if(state.channel)await db.removeChannel(state.channel);login()};
 if(state.sheet)editor();else if(state.view==='jogadores'&&gm())playerView();else dashboard();
}
async function leave(){if(state.dirty){await save();if(state.dirty){toast('Salve ou recarregue a ficha antes de sair.');return false;}}return !state.saving;}
function dashboard(){const secret=state.view==='secretas'&&gm();const ss=sheets().filter(s=>s.secret===secret);$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">${secret?'SÓ O MESTRE CONHECE':'SEU GRUPO, SEMPRE POR PERTO'}</div><h1>${secret?'Arquivo secreto':'Fichas da mesa'}</h1><p>${secret?'Monstros, NPCs e histórias que ainda não foram reveladas.':'As histórias da sua mesa, atualizadas a cada mudança.'}</p></div>${gm()?'<button class="primary" id="new-sheet">＋ Nova ficha</button>':''}</div><div class="stats"><div class="stat"><span>${secret?'Fichas secretas':'Personagens ativos'}</span><strong>${ss.filter(s=>!s.archived).length.toString().padStart(2,'0')}</strong></div><div class="stat"><span>${gm()?'Jogadores na mesa':'Suas fichas'}</span><strong>${gm()?players().length+' / '+table().max_players:ss.length}</strong></div><div class="stat"><span>${secret?'Visibilidade':'Sistema da ficha'}</span><strong style="font-size:24px">${secret?'Só você':'D&D 2024'}</strong></div></div><div class="toolbar"><div class="tabs"><button data-filter="all" class="${state.filter==='all'?'active':''}">Ativas</button><button data-filter="archived" class="${state.filter==='archived'?'active':''}">Arquivadas</button></div><input id="search" type="search" placeholder="Buscar por nome, classe ou espécie…" aria-label="Buscar fichas" value="${esc(state.search)}"></div><div id="cards"></div><p class="note" style="margin-top:26px">${secret?'◇ As fichas deste arquivo são acessíveis somente pelo mestre.':'As alterações são salvas automaticamente ao sair de cada campo.'}</p>`;
 if($('#new-sheet'))$('#new-sheet').onclick=()=>newSheet(secret);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;dashboard()});$('#search').oninput=e=>{state.search=e.target.value;cards(secret)};cards(secret);
}
function cards(secret){const list=sheets().filter(s=>s.secret===secret&&s.archived===(state.filter==='archived')&&[s.name,s.data.class,s.data.species].some(v=>String(v||'').toLowerCase().includes(state.search.toLowerCase())));$('#cards').innerHTML=list.length?`<div class="cards">${list.map(s=>{const d=s.data,p=state.players.find(p=>p.id===s.player_id);return `<article class="card"><div class="card-top"><div class="avatar">${esc(s.name.charAt(0).toUpperCase())}</div><div><span class="badge">${s.secret?'◇ Secreta · ':''}${esc(s.kind)}</span><h3>${esc(s.name)}</h3><small>${esc(d.species||'Espécie não definida')} · ${esc(d.class||'Sem classe')}</small></div></div><div class="card-body"><small>${esc(p?.name||'Ficha do mestre')}</small><div class="mini-stats"><div><b>${esc(d.level||1)}</b><span>NÍVEL</span></div><div><b>${esc(d.ac??10)}</b><span>ARMADURA</span></div><div><b>${esc(d.hp??0)}<small> / ${esc(d.hp_max??0)}</small></b><span>PONTOS DE VIDA</span></div></div><div class="hpbar"><i style="width:${Math.min(100,Math.max(0,Number(d.hp||0)/Math.max(1,Number(d.hp_max||1))*100))}%"></i></div><button data-open="${s.id}">Abrir ficha <span aria-hidden="true">↗</span></button></div></article>`}).join('')}</div>`:`<div class="empty"><div class="sigil" aria-hidden="true">${secret?'◇':'✧'}</div><h2>${state.search?'Nenhuma ficha encontrada':state.filter==='archived'?'Nenhuma ficha arquivada':secret?'Guarde aqui seus segredos':'Uma mesa pronta para novas histórias'}</h2><p>${state.search?'Tente outro nome, classe ou espécie.':gm()?'Crie uma ficha e dê início à próxima aventura. Você pode adicionar os jogadores e definir o limite da mesa.':state.table?'Seu mestre ainda não atribuiu uma ficha a você.':'Peça ao mestre para adicionar seu e-mail à mesa, ou crie sua própria mesa para mestrar.'}</p>${!state.table?'<button class="primary" id="empty-create">Criar minha mesa</button>':''}</div>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.sheet=structuredClone(state.sheets.find(s=>s.id===b.dataset.open));state.tab='principal';state.dirty=false;state.conflict=false;render()});if($('#empty-create'))$('#empty-create').onclick=newTable;}
function modal(title,body,submit){const d=$('#dialog');d.innerHTML=`<form><h2>${title}</h2>${body}<p class="error" id="modal-error" role="alert"></p><div class="actions"><button type="button" id="cancel">Cancelar</button><button class="primary">Salvar</button></div></form>`;$('#cancel').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('.primary');b.disabled=true;try{await submit(new FormData(e.target));d.close();await load();render();}catch(err){$('#modal-error').textContent=err.message;}finally{b.disabled=false;}};d.showModal();}
function newTable(){modal('Uma nova mesa','<label>Nome da mesa<input name="name" required maxlength="100" placeholder="Ex.: As Crônicas de Valdora"></label><label>Limite de jogadores<input name="limit" type="number" min="1" max="1000" value="6" required></label><p class="note">Você será o mestre desta mesa e poderá alterar o limite depois.</p>',async f=>{const t=await result(db.from('dnd_tables').insert({name:f.get('name').trim(),max_players:Number(f.get('limit'))}).select().single());state.table=t.id;state.view='fichas';state.sheet=null;toast('Mesa criada. Bem-vindo à aventura!')})}
function newSheet(secret){modal(secret?'Nova ficha secreta':'Nova ficha','<label>Nome<input name="name" required maxlength="150" placeholder="Nome do personagem"></label>'+ (secret?'<label>Tipo<select name="kind"><option value="npc">NPC</option><option value="monstro">Monstro</option><option value="personagem">Personagem secreto</option></select></label><p class="note">Somente você poderá ler e editar esta ficha.</p>':`<label>Jogador responsável<select name="player"><option value="">Mestre (sem jogador)</option>${players().map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>`),async f=>{const s=await result(db.from('dnd_sheets').insert({table_id:state.table,name:f.get('name').trim(),secret,kind:secret?f.get('kind'):'personagem',player_id:secret?null:f.get('player')||null,data:{level:1,ac:10,hp:0,hp_max:0,str:10,dex:10,con:10,int:10,wis:10,cha:10,proficiency:2}}).select().single());state.sheet=s;state.tab='principal';state.dirty=false;state.conflict=false;toast('Ficha criada.')})}
function playerView(){const ps=players();$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">CADA AVENTUREIRO TEM SEU LUGAR</div><h1>Jogadores</h1><p>Adicione os e-mails que terão acesso às fichas atribuídas.</p></div><button class="primary" id="add-player">＋ Adicionar jogador</button></div><section class="panel"><div class="row"><div><h3>Vagas à sua maneira</h3><p>${ps.length} de ${table().max_players} vagas ocupadas. O mestre não ocupa uma vaga.</p></div><button id="limit">Alterar limite</button></div>${ps.map(p=>`<div class="row"><div><b>${esc(p.name)}</b><p>${esc(p.email)} · ${sheets().filter(s=>s.player_id===p.id&&!s.archived).length} ficha(s)</p></div><button data-remove="${p.id}" class="quiet danger">Remover acesso</button></div>`).join('')||'<p style="margin-top:20px">Nenhum jogador adicionado ainda.</p>'}</section><p class="note">Compartilhe o endereço do site com seus jogadores. Eles devem criar uma conta usando o e-mail adicionado aqui. Nenhum convite é enviado automaticamente.</p><button id="copy-link">Copiar endereço do site</button>`;
 $('#limit').onclick=()=>modal('Limite de jogadores',`<label>Quantidade máxima<input name="limit" type="number" min="${Math.max(1,ps.length)}" max="1000" value="${table().max_players}" required></label>`,async f=>{await result(db.from('dnd_tables').update({max_players:Number(f.get('limit'))}).eq('id',state.table));toast('Limite atualizado.')});
 $('#add-player').onclick=()=>modal('Adicionar jogador','<label>Nome<input name="name" required maxlength="100"></label><label>E-mail da conta<input type="email" name="email" required></label>',async f=>{const email=f.get('email').trim().toLowerCase();const old=state.players.find(p=>p.table_id===state.table&&p.email===email);if(old?.active)throw Error('Este jogador já está na mesa.');await result(old?db.from('dnd_players').update({active:true,name:f.get('name').trim()}).eq('id',old.id):db.from('dnd_players').insert({table_id:state.table,name:f.get('name').trim(),email}));toast('Jogador adicionado. Atribua uma ficha a ele.')});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>modal('Remover acesso?','<p>O jogador perderá acesso às fichas desta mesa. Suas fichas serão preservadas para o mestre.</p>',async()=>{await result(db.from('dnd_players').update({active:false}).eq('id',b.dataset.remove));toast('Acesso removido.')}));$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin);toast('Endereço copiado.')}catch{toast('Copie o endereço na barra do navegador.')}};
}
function field(key,label,type='text',def='',attrs=''){const v=state.sheet.data[key]??def;return `<label>${label}<input data-field="${key}" type="${type}" value="${esc(v)}" ${attrs}></label>`}
function area(key,label){return `<label class="field-wide">${label}<textarea data-field="${key}">${esc(state.sheet.data[key]||'')}</textarea></label>`}
function check(key,label){return `<label class="checkline"><input data-field="${key}" type="checkbox" ${state.sheet.data[key]?'checked':''}>${label}</label>`}
function editor(){const s=state.sheet;$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">${s.secret?'◇ ARQUIVO SECRETO DO MESTRE':'FICHA DE PERSONAGEM'}${s.archived?' · ARQUIVADA':''}</div><h1>${esc(s.name)}</h1><p id="saved-at">Atualizada ${new Date(s.updated_at).toLocaleString('pt-BR')}</p></div><div class="actions"><button id="back">← Voltar</button>${gm()?'<button id="access">Gerenciar ficha</button>':''}<button id="print">Imprimir</button></div></div><div class="toolbar"><div class="tabs">${[['principal','Personagem'],['pericias','Perícias'],['combate','Combate'],['magias','Magias'],['historia','História e inventário']].map(([k,l])=>`<button data-tab="${k}" class="${state.tab===k?'active':''}">${l}</button>`).join('')}</div><span class="badge">D&D · 2024</span></div><div id="fields"></div><div class="savebar"><span id="save-status">${state.dirty?'Alterações pendentes':'✓ Todas as alterações salvas'}</span><div class="actions"><button id="reload" class="quiet">Recarregar</button><button id="save" class="primary">Salvar agora</button></div></div>`;
 $('#fields').innerHTML=fields();document.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>{const key=el.dataset.field;const v=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(el.type==='number'&&!el.checkValidity()){el.reportValidity();return;}if(key==='name')state.sheet.name=v;else state.sheet.data[key]=v;state.dirty=true;$('#save-status').textContent='Alterações pendentes…';if(abilities.some(a=>a[0]===key)){el.closest('.ability').querySelector('output').textContent=signed(mod(v));}if(el.tagName==='SELECT'&&el.closest('.skill')){const ability=key.startsWith('save_')?key.slice(5):skills[Number(key.slice(6))][1];el.closest('.skill').querySelector('b').textContent=signed(mod(state.sheet.data[ability])+Number(v)*Number(state.sheet.data.proficiency??2));}clearTimeout(timer);timer=setTimeout(save,600)});
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;editor()});$('#back').onclick=async()=>{if(await leave()){state.sheet=null;render()}};$('#save').onclick=save;$('#reload').onclick=()=>modal('Recarregar a ficha?','<p>As alterações locais ainda não salvas serão descartadas e a versão mais recente será carregada.</p>',async()=>{clearTimeout(timer);const fresh=await result(db.from('dnd_sheets').select('*').eq('id',s.id).single());state.sheet=fresh;state.dirty=false;state.conflict=false});$('#print').onclick=printSheet;if($('#access'))$('#access').onclick=async()=>{if(!await leave())return;manageSheet()};
}
function fields(){const d=state.sheet.data;switch(state.tab){case 'principal':return `<section class="panel"><h3>Identidade</h3><div class="grid"><label class="field-wide">Nome do personagem<input data-field="name" value="${esc(state.sheet.name)}" maxlength="150" required></label>${field('background','Antecedente')}${field('class','Classe')}${field('subclass','Subclasse')}${field('species','Espécie')}${field('level','Nível','number',1,'min="1" max="20"')}${field('xp','Experiência (XP)','number',0,'min="0"')}</div></section><section class="panel"><h3>Atributos</h3><div class="grid six">${abilities.map(([k,l])=>`<div class="ability">${field(k,l,'number',10,'min="1" max="30"')}<output>${signed(mod(d[k]))}</output><small class="subtle">modificador</small></div>`).join('')}</div></section><section class="panel"><h3>Essenciais</h3><div class="grid">${field('proficiency','Bônus de proficiência','number',2,'min="0"')}${field('speed','Deslocamento','text','9 m')}${field('size','Tamanho','text','Médio')}${field('passive','Percepção passiva','number',10,'min="0"')}${field('initiative','Iniciativa','number',0)}${check('inspiration','Inspiração heroica')}</div></section><section class="panel"><h3>Características e talentos</h3><div class="grid">${area('features','Características de classe')}${area('species_traits','Traços de espécie')}${area('feats','Talentos')}</div></section>`;
 case 'pericias':return `<section class="panel"><h3>Salvaguardas</h3><p class="note">Bônus calculados a partir dos atributos e da proficiência informada na ficha.</p><div class="grid two">${abilities.map(([k,l])=>proficiency('save_'+k,l,k)).join('')}</div></section><section class="panel"><h3>Perícias</h3><div class="grid two">${skills.map(([l,k],i)=>proficiency('skill_'+i,l,k)).join('')}</div></section><section class="panel"><h3>Treinamento e proficiências</h3><div class="grid">${check('armor_light','Armadura leve')}${check('armor_medium','Armadura média')}${check('armor_heavy','Armadura pesada')}${check('shields','Escudos')}${area('weapons_training','Armas')}${area('tools','Ferramentas')}</div></section>`;
 case 'combate':return `<section class="panel"><h3>Defesa e vitalidade</h3><div class="grid">${field('ac','Classe de armadura','number',10,'min="0"')}${field('hp','PV atuais','number',0,'min="0"')}${field('hp_max','PV máximos','number',0,'min="0"')}${field('hp_temp','PV temporários','number',0,'min="0"')}${field('hit_dice','Dado de vida','text','1d8')}${field('hit_dice_used','Dados de vida gastos','number',0,'min="0"')}${field('hit_dice_max','Dados de vida máximos','number',1,'min="0"')}${check('shield','Escudo equipado')}</div></section><section class="panel"><h3>Salvaguardas contra morte</h3><div class="grid two">${field('death_success','Sucessos','number',0,'min="0" max="3"')}${field('death_failure','Falhas','number',0,'min="0" max="3"')}</div></section><section class="panel"><h3>Armas e truques de dano</h3><p class="note">Registre nome, bônus de ataque ou CD, dano, tipo e notas.</p>${area('attacks','Ataques')}</section><section class="panel"><h3>Condições e recursos</h3>${area('conditions','Condições, resistências, ações e recursos limitados')}</section>`;
 case 'magias':return `<section class="panel"><h3>Conjuração</h3><div class="grid">${field('casting_ability','Atributo de conjuração')}${field('casting_mod','Modificador de conjuração','number',0)}${field('spell_dc','CD para evitar magia','number',10,'min="0"')}${field('spell_attack','Bônus de ataque mágico','number',0)}</div></section><section class="panel"><h3>Espaços de magia</h3><div class="grid">${Array.from({length:9},(_,i)=>`<div class="panel" style="margin:0;padding:14px"><span class="badge">${i+1}º círculo</span><div class="grid two" style="margin-top:12px">${field('slots_'+i,'Total','number',0,'min="0"')}${field('spent_'+i,'Gastos','number',0,'min="0"')}</div></div>`).join('')}</div></section><section class="panel"><h3>Truques e magias preparadas</h3><p class="note">Registre círculo, nome, tempo de conjuração, alcance, concentração, ritual, materiais e notas.</p>${area('spells','Lista de magias')}</section>`;
 case 'historia':return `<section class="panel"><h3>Quem vive nesta ficha</h3><div class="grid">${area('appearance','Aparência')}${area('history','História e personalidade')}${field('alignment','Alinhamento')}${field('languages','Idiomas')}</div></section><section class="panel"><h3>Equipamento</h3><div class="grid">${area('equipment','Inventário')}${field('attuned_1','Item mágico sintonizado 1')}${field('attuned_2','Item mágico sintonizado 2')}${field('attuned_3','Item mágico sintonizado 3')}</div></section><section class="panel"><h3>Moedas</h3><div class="grid">${[['cp','Cobre (PC)'],['sp','Prata (PP)'],['ep','Electro (PE)'],['gp','Ouro (PO)'],['pp','Platina (PL)']].map(([k,l])=>field(k,l,'number',0,'min="0"')).join('')}</div></section>`;}}
function proficiency(key,label,ability){const d=state.sheet.data,n=Number(d[key]||0),bonus=mod(d[ability])+n*Number(d.proficiency??2);return `<div class="skill"><span><b>${signed(bonus)}</b>${label}</span><select data-field="${key}" aria-label="Proficiência em ${label}"><option value="0" ${n===0?'selected':''}>Sem treino</option><option value="1" ${n===1?'selected':''}>Proficiente</option><option value="2" ${n===2?'selected':''}>Especialista</option></select></div>`}
async function save(){clearTimeout(timer);if(!state.dirty||state.saving||!state.sheet)return;state.saving=true;const snapshot=structuredClone(state.sheet);const status=$('#save-status');if(status)status.textContent='Salvando…';try{if(!snapshot.name.trim())throw Error('Preencha o nome do personagem.');const fresh=await result(db.from('dnd_sheets').update({name:snapshot.name.trim(),data:snapshot.data}).eq('id',snapshot.id).eq('version',snapshot.version).select().maybeSingle());if(!fresh){state.conflict=true;throw Error('A ficha mudou em outra tela. Copie suas alterações e use Recarregar antes de editar novamente.');}const unchanged=JSON.stringify(state.sheet.data)===JSON.stringify(snapshot.data)&&state.sheet.name===snapshot.name;state.sheet.version=fresh.version;state.sheet.updated_at=fresh.updated_at;state.dirty=!unchanged;const idx=state.sheets.findIndex(s=>s.id===fresh.id);if(idx>=0)state.sheets[idx]=fresh;if(status)status.textContent=state.dirty?'Novas alterações pendentes…':'✓ Todas as alterações salvas';if($('#saved-at'))$('#saved-at').textContent='Atualizada '+new Date(fresh.updated_at).toLocaleString('pt-BR');}catch(err){if(status)status.textContent=state.conflict?'Conflito de edição — recarregue a ficha':'Não salvo — tente novamente';fail(err);}finally{state.saving=false;if(state.dirty&&!state.conflict&&JSON.stringify(state.sheet.data)!==JSON.stringify(snapshot.data))timer=setTimeout(save,600);}}
function manageSheet(){const s=state.sheet;modal('Gerenciar ficha',`<label>Jogador responsável<select name="player" ${s.secret?'disabled':''}><option value="">Mestre (sem jogador)</option>${players().map(p=>`<option value="${p.id}" ${s.player_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="checkline"><input type="checkbox" name="archived" ${s.archived?'checked':''}> Arquivar ficha</label><p class="note">${s.secret?'Esta ficha permanece secreta e exclusiva do mestre.':'O jogador selecionado terá acesso para ler e editar esta ficha.'}</p>`,async f=>{const fresh=await result(db.from('dnd_sheets').update({player_id:s.secret?null:f.get('player')||null,archived:f.has('archived')}).eq('id',s.id).eq('version',s.version).select().maybeSingle());if(!fresh)throw Error('A ficha mudou. Recarregue antes de alterar o acesso.');state.sheet=fresh;toast('Ficha atualizada.')})}
window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',changed);
db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){state.user=null;state.sheet=null;state.dirty=false;clearTimeout(timer);login();}if(event==='TOKEN_REFRESHED'&&session)state.user=session.user;});
try{const {data:{session},error}=await db.auth.getSession();if(error)throw error;if(session)await start(session.user);else login();}catch(err){login();fail(err)}

function printSheet(){const selected=state.tab;const container=document.createElement('div');container.id='print-sheet';container.innerHTML='<h1>'+esc(state.sheet.name)+'</h1>'+['principal','pericias','combate','magias','historia'].map(tab=>{state.tab=tab;return fields()}).join('');state.tab=selected;container.querySelectorAll('textarea').forEach(el=>{const p=document.createElement('p');p.style.whiteSpace='pre-wrap';p.textContent=el.value||'—';el.replaceWith(p)});document.body.append(container);window.print();container.remove();}
